 main.innerHTML=`<div class="container"><section class="hero"><div class="hero-copy"><h1>Your next game.<br>Your kind of price.</h1><p>Pick the game. Set your budget. Get an email when tickets hit your price.</p><div class="hero-actions"><a class="button primary" href="./new.html">Create a ticket alert ${icon('arrow')}</a><a class="button secondary" href="./index.html?cheap=1">See what’s cheap</a></div><div class="hero-note">${icon('check')} Fees included ${icon('check')} Seats together ${icon('check')} No need to keep checking</div></div>${stadiumArt()}</section><section class="explore-section" aria-labelledby="explore-title"><div class="section-heading"><div><h2 id="explore-title">${state.cheapOnly?'What’s cheap coming up.':'Find your next one.'}</h2><p>${state.cheapOnly?'Browse recently checked get-in prices. Enter a city or state to make it yours.':'The game, the gig, the night you don’t want to miss.'}</p></div><a class="text-link" href="./new.html?kind=team">Follow a whole team ${icon('arrow')}</a></div><div class="explore-layout"><div class="explore-main">${searchControls()}<div class="results-meta"><span id="results-count" role="status">Finding upcoming events…</span><span>Get-in prices per ticket · check exact quantity on event page</span></div><p id="price-request-status" class="price-request-status" role="status" hidden></p><div id="events">${loadingRows()}</div><button id="more-events" class="button secondary load-more" hidden>Show more events</button></div><aside class="explore-aside"><div class="playbook"><span class="playbook-icon">${icon('bell')}</span><h3>Less refreshing.<br>More being there.</h3><p>A ticket alert keeps an eye on your price, so you can get on with your day.</p><ol><li><span>Pick your event</span><small>One game, a team, or a day out.</small></li><li><span>Call your price</span><small>Your budget, with fees included.</small></li><li><span>Watch your inbox</span><small>A link to the tickets when they match.</small></li></ol><a class="button white" href="./new.html">Set up an alert ${icon('arrow')}</a></div><div class="aside-note">${icon('shield')}<p><strong>You make the call.</strong> We find matching listings. You choose whether to buy on Gametime.</p></div><div class="source-note">${icon('clock')}<span>Checks target every 15 minutes near game day. <a href="./notifications.html">How delivery works</a></span></div></aside></div></section></div>`;
 bindSearch(loadEvents);$('#more-events').onclick=()=>{state.offset+=12;loadEvents(true);};loadEvents();
