async function builder(){
 state.kind=query.get('kind')==='team'?'team':'event';
 if(query.has('edit')||query.has('event')){
 layout('Getting your alert ready.','One moment while we load the details.',loadingRows(2));
 try {
 if(query.has('edit')){const [w]=await sbGet('tix_watches?id=eq.'+encodeURIComponent(query.get('edit'))+'&select=*');if(!w)throw new Error('This alert was removed. Start a new alert from Find events.');state.edit=w;state.kind=w.kind;state.qty=w.qty;state.threshold=(w.threshold_cents/100).toString();state.clubs=w.clubs||[];state.clubLevel=w.match.club_level??!!w.clubs.length;state.homeAway=w.match.home_away||'home';state.alertStyle=w.alert_style;state.emailEnabled=w.email_enabled!==false;state.smsEnabled=!!w.sms_enabled;state.label=w.label;state.category=w.match.category||state.category;try{const meta=await sbRpc('tix_destination_meta',{p_watch_id:w.id});state.destinationConfigured=!!meta?.configured;state.provider=meta?.provider||'';state.existingProvider=state.provider;}catch{}if(w.kind==='team')state.selected={team:w.match.slug};else if(w.kind==='date')state.selected={date:w.match.date,city:w.match.city,state:w.match.state,venue_slug:w.match.venue_slug};else{const [event]=await sbGet('tix_events_v?event_id=eq.'+encodeURIComponent(w.match.event_ids[0])+'&select=*');if(!event)throw new Error('This event is no longer in the catalog. Create a new alert for an upcoming event.');state.selected=event;}}
 else{const [event]=await sbGet('tix_events_v?event_id=eq.'+encodeURIComponent(query.get('event'))+'&select=*');if(!event)throw new Error('This event is no longer available. Find another event to watch.');state.selected=event;}
 state.step=2;renderBuilder();loadClubs();
 }catch(e){layout('Let’s find another event.','Your alert has not changed.',errorBox(e.message,'')+'<a class="button primary" href="./new.html">Start a new alert</a>');}return;
 }renderBuilder();
}
